import itertools

def is_magic(seq):
    n = len(seq)
    for i in range(n):
        count = sum(1 for x in seq if x == i)
        if seq[i] != count:
            return False
    return True

found = False
for candidate in itertools.product(range(7), repeat=6):
    if sum(candidate) == 6 or True:  # actually don't assume sum==6
        if is_magic(candidate):
            print(candidate)
            found = True
            break

print("Found:", found)
